
import pandas as pd


# ============================================================
# 1. LOAD PREDICTED AND ACTUAL INCIDENTS
# ============================================================

# Load the incidents predicted by our system
predicted_df = pd.read_csv("data/classified_incidents_test.csv")

# Load the actual incidents generated by the simulator
actual_df = pd.read_csv("data/incident_log_test.csv")

# Load the original test telemetry
telemetry_df = pd.read_csv("data/robot_telemetry_test.csv")

# Convert timestamps to datetime
predicted_df["start_time"] = pd.to_datetime(predicted_df["start_time"])
predicted_df["end_time"] = pd.to_datetime(predicted_df["end_time"])
telemetry_df["timestamp"] = pd.to_datetime(telemetry_df["timestamp"])

print("Predicted incidents:", len(predicted_df))
print("Actual incidents:", len(actual_df))


# ============================================================
# 2. CONVERT ACTUAL INCIDENT SECONDS TO TIMESTAMPS
# ============================================================

# Find the first telemetry timestamp for each robot
simulation_starts = (
    telemetry_df.groupby("robot_id")["timestamp"].min()
)

# Match each actual incident with its robot's starting timestamp
actual_df["simulation_start"] = actual_df["robot_id"].map(
    simulation_starts
)

# Calculate the last second of each actual incident
actual_df["end_second"] = (
    actual_df["start_second"] + actual_df["duration"] - 1
)

# Convert actual incident start seconds into timestamps
actual_df["start_time"] = (
    actual_df["simulation_start"]
    + pd.to_timedelta(actual_df["start_second"], unit="s")
)

# Convert actual incident end seconds into timestamps
actual_df["end_time"] = (
    actual_df["simulation_start"]
    + pd.to_timedelta(actual_df["end_second"], unit="s")
)

print("\nActual incidents with timestamps:")
print(
    actual_df[
        ["robot_id", "incident_type", "start_time", "end_time"]
    ].head(10).to_string(index=False)
)


# ============================================================
# 3. MATCH PREDICTED INCIDENTS WITH ACTUAL INCIDENTS
# ============================================================

# Store matching results
matches = []

# Keep track of actual incidents that were detected
detected_actual_ids = set()

# Loop through every predicted incident
for predicted_id, predicted in predicted_df.iterrows():

    # Find actual incidents involving the same robot
    same_robot = actual_df[
        actual_df["robot_id"] == predicted["robot_id"]
    ]

    # Find actual incidents whose time intervals overlap
    overlapping = same_robot[
        (same_robot["start_time"] <= predicted["end_time"])
        & (same_robot["end_time"] >= predicted["start_time"])
    ]

    # Check whether an actual incident overlaps
    if not overlapping.empty:

        # Calculate the overlap duration for each candidate
        overlap_start = overlapping["start_time"].clip(
            lower=predicted["start_time"]
        )

        overlap_end = overlapping["end_time"].clip(
            upper=predicted["end_time"]
        )

        overlap_seconds = (
            overlap_end - overlap_start
        ).dt.total_seconds()

        # Select the actual incident with the largest overlap
        actual_id = overlap_seconds.idxmax()
        actual = actual_df.loc[actual_id]

        # Mark this actual incident as detected
        detected_actual_ids.add(actual_id)

        # Check whether the predicted type is correct
        correct_type = (
            predicted["predicted_incident_type"]
            == actual["incident_type"]
        )

        matches.append({
            "predicted_incident_id": predicted["incident_id"],
            "robot_id": predicted["robot_id"],
            "predicted_type": predicted["predicted_incident_type"],
            "actual_type": actual["incident_type"],
            "matched": True,
            "correct_type": correct_type
        })

    else:

        # No actual incident overlaps this prediction
        matches.append({
            "predicted_incident_id": predicted["incident_id"],
            "robot_id": predicted["robot_id"],
            "predicted_type": predicted["predicted_incident_type"],
            "actual_type": "none",
            "matched": False,
            "correct_type": False
        })


# ============================================================
# 4. CALCULATE EVALUATION METRICS
# ============================================================

# Convert matching results into a DataFrame
matches_df = pd.DataFrame(matches)

# Count unique actual incidents detected
detected_count = len(detected_actual_ids)

# Count actual incidents missed
missed_count = len(actual_df) - detected_count

# Count predictions that do not overlap actual incidents
false_positive_count = (~matches_df["matched"]).sum()

# Count predictions with matching incident types
correct_classifications = matches_df["correct_type"].sum()

# Count all predictions overlapping actual incidents
matched_predictions = matches_df["matched"].sum()

# Calculate detection recall
detection_recall = detected_count / len(actual_df)

# Calculate classification accuracy among overlapping predictions
classification_accuracy = (
    correct_classifications / matched_predictions
    if matched_predictions > 0 else 0
)


# ============================================================
# 5. DISPLAY EVALUATION RESULTS
# ============================================================

print("\n========== EVALUATION RESULTS ==========")

print(f"Actual incidents: {len(actual_df)}")
print(f"Predicted incidents: {len(predicted_df)}")
print(f"Actual incidents detected: {detected_count}")
print(f"Actual incidents missed: {missed_count}")
print(f"Unmatched predictions: {false_positive_count}")

print(f"Detection recall: {detection_recall:.2%}")
print(f"Classification accuracy (matched predictions): {classification_accuracy:.2%}")


# ============================================================
# 6. SAVE EVALUATION RESULTS
# ============================================================

matches_df.to_csv(
    "data/incident_evaluation_test.csv",
    index=False
)

print("\nEvaluation results saved successfully.")
